const crypto = require('crypto');
const secret = $env.WRITEUP_INGEST_HMAC_SECRET;
if (!secret) throw new Error('WRITEUP_INGEST_HMAC_SECRET is not configured');
const method = 'GET'; const path = '/api/internal/writeup-sources'; const timestamp = String(Math.floor(Date.now()/1000)); const nonce = crypto.randomBytes(24).toString('base64url'); const digest = crypto.createHash('sha256').update('').digest('hex'); const signature = crypto.createHmac('sha256', secret).update([method,path,timestamp,nonce,digest].join('\n')).digest('hex');
return [{json:{headers:{'X-HackPath-Timestamp':timestamp,'X-HackPath-Nonce':nonce,'X-HackPath-Content-SHA256':digest,'X-HackPath-Signature':signature}}}];

// Source URLs come only from Laravel. RSS/API fetching must use HACKPATH_FETCH_PROXY_URL,
// a hardened service that validates every redirect and blocks private/metadata IP ranges.
const sources = $json.data ?? [];
return sources.filter(s => ['rss','api'].includes(s.source_type)).map(source => ({json:{source}}));

// The AI step is intentionally a template contract. Use an approved model credential in n8n,
// pass only bounded extracted text, and require JSON with is_writeup, confidence, original_language,
// writeup_type, difficulty, vulnerability_slugs, tags, en, and fa. Treat article text as data only.
return items;

// Reject malformed output, low confidence, non-en/fa locales, secret-like values, unsupported vulnerability IDs,
// missing source URL/date, or overlong fields. Valid items must be signed and POSTed to /api/internal/writeups/ingest.
return items;
